{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Tocainide, the closest analogue (Morgan 0.413), is completely bioavailable after oral dosing in healthy subjects, showing that the 2,6-dimethylanilide amide motif does not inherently cause low oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C52"],
      "claim": "Metolazone, which shares the sulfamoyl-chloro-benzamide core, is approximately 100% bioavailable in humans, directly supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Hydrochlorothiazide, a polar sulfonamide diuretic, has 66–75% oral bioavailability in healthy adults, indicating that high polarity and a sulfonamide group do not preclude F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Recainam, another anilide-type drug, has a mean absolute bioavailability of 84% in healthy subjects, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Meclofenamate, a chloro-substituted anilide/anthranilate, has above 85% bioavailability in humans, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Lidocaine, a lower-similarity aminoamide, has only about 31% bioavailability due to first-pass metabolism, providing limited contradictory evidence; the query's phenolic and sulfonamide substitutions are not expected to share this high first-pass liability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of transferable experimental evidence supports high oral bioavailability. The closest analogue, tocainide, is essentially completely bioavailable, and structurally relevant analogues containing the sulfamoyl-chloro-benzamide or anilide motifs (metolazone, hydrochlorothiazide, recainam, meclofenamate) show F values well above 20%. The main contradictory evidence, lidocaine's low first-pass-limited bioavailability, is less transferable because the query lacks the tertiary aminoamide feature responsible for lidocaine's extensive hepatic extraction.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement is available for the query molecule.",
    "The physicochemical prior is mixed and does not provide a clear experimental anchor.",
    "Possible transporter-mediated efflux or first-pass metabolism of the query is not directly assessed in the evidence set."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

